\begin{theorem}\label{theorem:lowerboundi(G^2)closed}
    Let $G$ be a non-complete regular connected graph with adjacency eigenvalues $\lambda_1\ge \dots \ge \lambda_n$. Let $\Lambda$ be the maximum number of common neighbours of adjacent vertices of $G$, and let $M$ be the maximum number of neighbours of non-adjacent vertices of $G$. The following choices of $p$ are optimal for the bound of Theorem \ref{theorem:lowerboundi(G^t)} when $t=2$.
    \begin{enumerate}
        \item[i.] If $\Lambda-\lambda_n \le M+\lambda_2$, then $p=x^2+(M-\Lambda)x$, giving
        $$i(G^2) \ge \frac{(\lambda_1-\lambda_2)(\lambda_1+\lambda_2+M-\Lambda)}{2M}.$$
        \item[ii.] If $M+\lambda_2 \le \Lambda - \lambda_n \le \lambda_1$, then $p=x^2+(M-\Lambda)x$, giving
        $$i(G^2)\ge \frac{(\lambda_1-\lambda_n)(\lambda_1+\lambda_n+M-\Lambda)}{2M}.$$
        \item[iii.] If $\max(\lambda_1,M+\lambda_2) \le \Lambda-\lambda_n$, then $p=x^2-(\lambda_2+\lambda_n)x$, giving
        $$i(G^2)\ge \frac{(\lambda_1-\lambda_2)(\lambda_1-\lambda_n)}{2(\Lambda-\lambda_2-\lambda_n)}.$$
    \end{enumerate}
\end{theorem}

\begin{lemma}\label{lem:small-boundary-sets}
Let $\frac{n}{d^{\ln^2 d}}\le a\le \frac{n}{2}$. Then, the number of sets $A\subseteq V$ of size $a$ with $e(A,A^c)< a\ln^2d$ is at most $\exp\left\{\frac{2a}{\ln d}\right\}$.
\end{lemma}

\begin{proposition}\label{prop:tau-gluing}
Let $D$ be obtained by gluing the domains $D_1,\dots,D_m$ at~$p$. Then
\[
   \tau(D) = \begin{cases}
       \displaystyle \sum_{i=1}^m \tau(D_i) + (m-1),          &\text{if } p\in\partial D, \\[0.3cm]
       \displaystyle \sum_{i=1}^m \tau(D_i) - (d-m),           &\text{if } p\notin\partial D .
     \end{cases}
\]
In particular, gluing increases the total branching excess  $\tau$ by exactly  $m-1$ if  $p\in \partial D$, while $\tau$ remains unchanged or decreases if  $p \not\in \partial D$.
\end{proposition}

\begin{lemma}\label{lem:almost-indep}
    For distinct $i,j\in [\ell]$ with $|\ang{v_i, v_j}|\le 0.9$ and $t\in \{1,2,4,\dots,2^{\ceil{\log_2 m}}\}$, we have 
    \[\P[i\text{ bad}\text{ and }\cE_1(j,t)]\le  \frac{40000t}{\rho_0^2\sqrt{S_j}}\log m.\]
\end{lemma}

\begin{corollary}\label{cor:slicing}
    Let $C$ be a positive integer and let $\cH $ be a collection of hyperplanes in $\mathbb{R}^n$ with normal vectors in $\{-C, \dots, C\}^n$, such that every edge of the $n$-dimensional hypercube $[0,1]^n$ is sliced by a hyperplane in $\cH$. Then $|\cH|\ge n/(4C)$.
\end{corollary}

\begin{lemma}
\label{lem:mazur-map-section}
Let $1<p\leq2$ and let $q$ be  the H\"older conjugate of $p$, that is $\frac{1}{p} + \frac{1}{q} = 1$. For a nonzero vector $u\in\R^m$, define
\[
    J(u)=\frac{(|u_1|^{p-2}u_1,\ldots,|u_m|^{p-2}u_m)}{\|u\|_p^{p-1}}
\]
to be the vector in $\partial B_q^m$ such that $\langle J(u),u\rangle=\|u\|_p$.
Then, for nonzero $u,v\in\R^m$,
\begin{equation}
\label{eq:mazur-map-estimate-section}
    \|J(u)-J(v)\|_q
    \leq
    2\left(
       \frac{\|u-v\|_p}{\|u\|_p+\|v\|_p}
    \right)^{p-1}.
\end{equation}
\end{lemma}
